  computed: {
    currentScenarioData() {
      const scenario = this.scenarioData[this.currentScenario];
      const scenarioConfig = this.scenarios.find(s => s.id === this.currentScenario);
      return {
        ...scenario,
        title: scenarioConfig?.title || '',
        labels: scenarioConfig?.labels || {}
      };
    },
    sourceData() {
      return this.currentScenarioData.sourceData;
    },
    targetData: {
      get() {
        return this.currentScenarioData.targetData;
      },
      set(value) {
        this.currentScenarioData.targetData = value;
      }
    },
    responseSourceData() {
      return this.currentScenarioData.responseSourceData;
    },
    responseTargetData: {
      get() {
        return this.currentScenarioData.responseTargetData;
      },
      set(value) {
        this.currentScenarioData.responseTargetData = value;
      }
    },
    preProcessSteps() {
      return this.currentScenarioData.preProcessSteps;
    },
    postProcessSteps() {
      return this.currentScenarioData.postProcessSteps;
    },
    finalTargetData() {
      // 返回当前场景的完整目标数据（前置处理最终结果）
      const scenario = this.currentScenario;
      if (scenario === 'archive') {
        return {
          patientCode: "2509050001",
          name: "测试账号",
          sex: "2",
          age: "53",
          birthDate: "1972-02-25",
          cardId: "330511197202254629",
          phone: "13059970500",
          orgName: "测试单位"
        };
      } else if (scenario === 'apply') {
        return {
          patientId: "85184",
          clinicId: "2504280032",
          patientCode: "2504280032",
          name: "蔡培勤",
          age: "54",
          sex: "2",
          identitycard: "330502197101062226",
          birthDay: "1971-01-06",
          orders: [
            {
              sourceId: "80158314",
              ordersId: "1237",
              ordersDept: "1058",
              executeDept: "1058",
              ordersManId: "zqf0558",
              ordersDate: "2025-01-06 16:09:00",
              ordersName: "常规心电图检查",
              price: "20",
              factPrice: "20"
            }
          ]
        };
      } else if (scenario === 'charge') {
        return {
          patientId: "030001375",
          clinicId: "20250908000204",
          name: "测试账号",
          orderType: "1",
          amount: "170"
        };
      }
      return {};
    },
    totalSteps() {
      // 1:前置概览 2-N:前置字段 N+1:后置概览 N+2-M:后置字段
      return 1 + this.preProcessSteps.length + 1 + this.postProcessSteps.length;
    }
  },
  methods: {
    nextStep() {
      if (this.currentStep === 0) {
        // 步骤0 -> 1: 显示前置处理概览（无需应用数据）
        this.currentStep = 1;
      } else if (this.currentStep === 1) {
        // 步骤1 -> 2: 开始前置处理字段映射
        this.currentStep = 2;
        const step = this.preProcessSteps[0];
        if (step && step.apply) {
          step.apply.call(this);
        }
      } else if (this.currentStep >= 2 && this.currentStep < this.preProcessSteps.length + 1) {
        // 前置处理字段映射
        this.currentStep++;
        const stepIndex = this.currentStep - 2;
        if (stepIndex < this.preProcessSteps.length) {
          const step = this.preProcessSteps[stepIndex];
          if (step && step.apply) {
            step.apply.call(this);
          }
        }
      } else if (this.currentStep === this.preProcessSteps.length + 1) {
        // 显示后置处理概览
        this.currentStep++;
      } else if (this.currentStep > this.preProcessSteps.length + 1) {
        // 后置处理字段映射
        const stepIndex = this.currentStep - this.preProcessSteps.length - 2;
        if (stepIndex < this.postProcessSteps.length) {
          const step = this.postProcessSteps[stepIndex];
          if (step && step.apply) {
            step.apply.call(this);
          }
        }
        this.currentStep++;
      }
    },
    prevStep() {
      if (this.currentStep > 1) {
        this.currentStep--;
        this.resetData();
        // 重新应用所有已完成的步骤
        for (let i = 2; i <= this.currentStep; i++) {
          if (i <= this.preProcessSteps.length + 1) {
            const stepIndex = i - 2;
            if (stepIndex >= 0 && stepIndex < this.preProcessSteps.length) {
              const step = this.preProcessSteps[stepIndex];
              if (step && step.apply) {
                step.apply.call(this);
              }
            }
          } else if (i > this.preProcessSteps.length + 1) {
            const stepIndex = i - this.preProcessSteps.length - 2;
            if (stepIndex >= 0 && stepIndex < this.postProcessSteps.length) {
              const step = this.postProcessSteps[stepIndex];
              if (step && step.apply) {
                step.apply.call(this);
              }
            }
          }
        }
      }
    },
    reset() {
      this.currentStep = 1;
      this.resetData();
    },
    resetData() {
      this.currentScenarioData.targetData = {};
      this.currentScenarioData.responseTargetData = {};
    },
    switchScenario(scenarioId) {
      if (this.currentScenario === scenarioId) return;
      this.currentStep = 1;
      this.currentScenario = scenarioId;
      this.resetData();
    },
    formatJson(obj) {
      return JSON.stringify(obj, null, 2);
    },
    highlightJson(obj, highlightField) {
      if (!highlightField) {
        return this.formatJson(obj);
      }
      const jsonStr = this.formatJson(obj);
      // 简单的高亮实现：高亮字段名
      const fieldName = highlightField.split('.').pop().split('[')[0];
      const regex = new RegExp(`"${fieldName}"`, 'g');
      return jsonStr.replace(regex, `<span class="highlight-field">"${fieldName}"</span>`);
    },
    getCurrentSourceField() {
      if (this.currentStep > 1 && this.currentStep <= this.preProcessSteps.length + 1) {
        return this.preProcessSteps[this.currentStep - 2]?.source;
      }
      return null;
    },
    getCurrentTargetField() {
      if (this.currentStep > 1 && this.currentStep <= this.preProcessSteps.length + 1) {
        return this.preProcessSteps[this.currentStep - 2]?.target;
      }
      return null;
    },
    getCurrentResponseSourceField() {
      if (this.currentStep > this.preProcessSteps.length + 2) {
        const stepIndex = this.currentStep - this.preProcessSteps.length - 3;
        return this.postProcessSteps[stepIndex]?.source;
      }
      return null;
    },
    getCurrentResponseTargetField() {
      if (this.currentStep > this.preProcessSteps.length + 2) {
        const stepIndex = this.currentStep - this.preProcessSteps.length - 3;
        return this.postProcessSteps[stepIndex]?.target;
      }
      return null;
    },
    getMappingTypeTag(type) {
      const tagMap = {
        'NAME': 'success',
        'EXPRESSION': 'warning',
        'CONSTANT': 'info',
        'BEAN_EXPRESSION': 'warning',
        'SINGLE_MAP': 'success'
      };
      return tagMap[type] || 'info';
    },
    getMappingTypeText(type) {
      const textMap = {
        'NAME': '值映射',
        'EXPRESSION': '表达式',
        'CONSTANT': '固定值',
        'BEAN_EXPRESSION': '函数表达式',
        'SINGLE_MAP': '单值映射'
      };
      return textMap[type] || type;
    },
    getCurrentStep() {
      const index = this.currentStep - 2;
      return this.preProcessSteps[index] || {};
    },
    getCurrentPostStep() {
      const index = this.currentStep - this.preProcessSteps.length - 3;
      return this.postProcessSteps[index] || {};
    },
    getStepPhase() {
      if (this.currentStep === 1) return '(前置处理概览)';
      if (this.currentStep >= 2 && this.currentStep <= this.preProcessSteps.length + 1) {
        return '(前置处理 - 字段映射)';
      }
      if (this.currentStep === this.preProcessSteps.length + 2) return '(后置处理概览)';
      return '(后置处理 - 字段映射)';
    }
  }
};
